from collections import OrderedDict

def cache_sim(capacity, ttl, ops):
    store = OrderedDict()  # key -> (value, write_time)
    results = []

    def is_expired(key, t):
        _, wt = store[key]
        return wt + ttl <= t

    for op in ops:
        kind = op[0]
        t = op[1]
        key = op[2]

        if kind == 'put':
            value = op[3]
            if key in store:
                if is_expired(key, t):
                    del store[key]
                else:
                    # update existing, refresh order
                    del store[key]

            if key not in store:
                if len(store) >= capacity:
                    store.popitem(last=False)  # evict LRU

            store[key] = (value, t)
            store.move_to_end(key)

        elif kind == 'get':
            if key in store and not is_expired(key, t):
                value, wt = store[key]
                store.move_to_end(key)
                results.append(value)
            else:
                if key in store:
                    del store[key]
                results.append(-1)

    return results

